    /* ---- Music player state ------------------------------------------
       The player itself lives in the sidebar foot; the enabled-track list
       and the on/off switch are persisted here so the settings page and
       the player share one source of truth. */
    let musicPlayerVisible = true;
    let musicEnabled = null;
    let previewAudio = null;
    let pauseMainMusic = null;
    const musicStateListeners = new Set();
    const loadMusicEnabled = function () {
      if (musicEnabled) return musicEnabled;
      musicEnabled = {};
      for (const track of MUSIC_TRACKS) musicEnabled[track.id] = true;
      try {
        const raw = window.localStorage.getItem('cr-music-enabled');
        if (raw) {
          const parsed = JSON.parse(raw);
          if (parsed && typeof parsed === 'object') {
            for (const track of MUSIC_TRACKS) {
              if (typeof parsed[track.id] === 'boolean') musicEnabled[track.id] = parsed[track.id];
            }
          }
        }
      } catch (e) { /* keep every track enabled */ }
      return musicEnabled;
    };
    const musicTrackEnabled = function (id) {
      const map = loadMusicEnabled();
      return map[id] !== false;
    };
    const emitMusicState = function () {
      for (const fn of musicStateListeners) fn();
    };
    const useMusicState = function () {
      const state = React.useState(0);
      const force = state[1];
      React.useEffect(function () {
        const fn = function () { force(function (n) { return n + 1; }); };
        musicStateListeners.add(fn);
        return function () { musicStateListeners.delete(fn); };
      }, []);
      return musicPlayerVisible;
    };
    const setMusicPlayerVisible = function (next) {
      const value = Boolean(next);
      if (musicPlayerVisible === value) return;
      musicPlayerVisible = value;
      if (!value) stopMusicPreview();
      try {
        window.localStorage.setItem('cr-music-player-visible', value ? '1' : '0');
      } catch (e) { /* storage unavailable */ }
      emitMusicState();
    };
    const setMusicTrackEnabled = function (id, next) {
      const map = loadMusicEnabled();
      const value = Boolean(next);
      if (map[id] === value) return;
      map[id] = value;
      try {
        window.localStorage.setItem('cr-music-enabled', JSON.stringify(map));
      } catch (e) { /* storage unavailable */ }
      emitMusicState();
    };
    const restoreMusicState = function () {
      loadMusicEnabled();
      try {
        musicPlayerVisible = window.localStorage.getItem('cr-music-player-visible') !== '0';
      } catch (e) { /* keep visible */ }
    };
    const stopMusicPreview = function () {
      const audio = previewAudio;
      previewAudio = null;
      if (!audio) return;
      try {
        audio.pause();
        audio.currentTime = 0;
        audio.removeAttribute('src');
        audio.load();
      } catch (e) { /* preview cleanup is best-effort */ }
    };

    /* Settings previews use one audio element at a time. Starting a preview
       pauses the sidebar player and replaces any earlier preview. */
    const previewMusicTrack = function (id) {
      try {
        const track = MUSIC_TRACKS.find(function (t) { return t.id === id; });
        if (!track) return;
        if (pauseMainMusic) pauseMainMusic();
        if (previewAudio && previewAudio.__crPreviewTrackId === track.id) {
          stopMusicPreview();
          return;
        }
        stopMusicPreview();
        const audio = new window.Audio(track.url);
        previewAudio = audio;
        audio.__crPreviewTrackId = track.id;
        audio.volume = 0.6;
        const clear = function () {
          if (previewAudio === audio) previewAudio = null;
        };
        audio.addEventListener('ended', clear, { once: true });
        audio.addEventListener('error', clear, { once: true });
        const result = audio.play();
        if (result && typeof result.catch === 'function') {
          result.catch(function () { clear(); });
        }
      } catch (e) { /* preview is best-effort */ }
    };

